/**
 * Field mapping functions between Airtable records and domain models
 * Handles bidirectional transformation of data
 */

import type { 
  Quote, 
  LineItem, 
  AirtableQuoteRecord, 
  AirtableQuoteFields,
  AirtableLineItemRecord,
  AirtableLineItemFields 
} from './types';

// ============================================
// Quote Mappers
// ============================================

/**
 * Maps an Airtable quote record to our domain Quote model
 */
export function mapAirtableToQuote(record: AirtableQuoteRecord): Quote {
  const fields = record.fields;

  return {
    id: record.id,
    quoteId: fields['Quote ID'] || '',
    token: fields['Token'] || '',
    firstName: fields['First Name'] || '',
    lastName: fields['Last Name'] || '',
    email: fields['Email'] || '',
    city: fields['City'] || '',
    stories: fields['Stories'],
    squareFootage: fields['Square Footage'],
    lotSize: fields['Lot Size'],
    alaCarteTotal: fields['A La Carte Total'] || 0,
    handldTotal: fields['Handld Total'] || 0,
    alaCarteTotalAnnual: fields['A La Carte Total Annual'],
    handldTotalAnnual: fields['Handld Total Annual'],
    selectedServices: fields['Selected Services'] || [],
    createdAt: fields['Created At'] || record.createdTime,
    updatedAt: fields['Updated At']
  };
}

/**
 * Maps our domain Quote model back to Airtable fields for updates
 * Only includes fields that are defined (partial update)
 */
export function mapQuoteToAirtable(quote: Partial<Quote>): Partial<AirtableQuoteFields> {
  const fields: Partial<AirtableQuoteFields> = {};

  if (quote.quoteId !== undefined) fields['Quote ID'] = quote.quoteId;
  if (quote.token !== undefined) fields['Token'] = quote.token;
  if (quote.firstName !== undefined) fields['First Name'] = quote.firstName;
  if (quote.lastName !== undefined) fields['Last Name'] = quote.lastName;
  if (quote.email !== undefined) fields['Email'] = quote.email;
  if (quote.city !== undefined) fields['City'] = quote.city;
  if (quote.stories !== undefined) fields['Stories'] = quote.stories;
  if (quote.squareFootage !== undefined) fields['Square Footage'] = quote.squareFootage;
  if (quote.lotSize !== undefined) fields['Lot Size'] = quote.lotSize;
  if (quote.alaCarteTotal !== undefined) fields['A La Carte Total'] = quote.alaCarteTotal;
  if (quote.handldTotal !== undefined) fields['Handld Total'] = quote.handldTotal;
  if (quote.alaCarteTotalAnnual !== undefined) fields['A La Carte Total Annual'] = quote.alaCarteTotalAnnual;
  if (quote.handldTotalAnnual !== undefined) fields['Handld Total Annual'] = quote.handldTotalAnnual;
  if (quote.selectedServices !== undefined) fields['Selected Services'] = quote.selectedServices;

  return fields;
}

/**
 * Calculates quote totals from the quote fields
 */
export function calculateQuoteTotals(quote: Quote) {
  // Prefer annual totals if available
  const alacarteTotal = quote.alaCarteTotalAnnual || quote.alaCarteTotal || 0;
  const memberTotal = quote.handldTotalAnnual || quote.handldTotal || 0;

  return {
    alacarteTotal,
    memberTotal,
    savings: alacarteTotal - memberTotal
  };
}

// ============================================
// LineItem Mappers
// ============================================

/**
 * Maps an Airtable line item record to our domain LineItem model
 */
export function mapAirtableToLineItem(record: AirtableLineItemRecord): LineItem {
  const fields = record.fields;

  // Convert string frequency to number (e.g., "5" -> 5)
  const frequency = fields['Chosen Frequency'] ? parseInt(fields['Chosen Frequency'], 10) : undefined;

  // Handle pricing fields - can be arrays or single values, and have different field names
  let handldRate = 0;
  let alaCarteRate = 0;

  // Try "Handld Price" first, then "Handld Rate"
  if (fields['Handld Price'] !== undefined) {
    handldRate = Array.isArray(fields['Handld Price']) 
      ? fields['Handld Price'][0] || 0
      : fields['Handld Price'] || 0;
  } else if (fields['Handld Rate'] !== undefined) {
    handldRate = fields['Handld Rate'] || 0;
  }

  // Try "A La Carte Price" first, then "A La Carte Rate"
  if (fields['A La Carte Price'] !== undefined) {
    alaCarteRate = Array.isArray(fields['A La Carte Price'])
      ? fields['A La Carte Price'][0] || 0
      : fields['A La Carte Price'] || 0;
  } else if (fields['A La Carte Rate'] !== undefined) {
    alaCarteRate = fields['A La Carte Rate'] || 0;
  }

  return {
    id: record.id,
    service: fields['Service'] || '',
    description: fields['Description'],
    handldRate,
    alaCarteRate,
    chosenFrequency: isNaN(frequency!) ? undefined : frequency,
    unit: fields['Unit'],
    quoteId: fields['Quote ID (from Request)'] || '',
    linkToQuote: fields['Link to Quote Request']
  };
}

/**
 * Maps our domain LineItem model back to Airtable fields for updates
 * Only includes fields that are defined (partial update)
 */
export function mapLineItemToAirtable(lineItem: Partial<LineItem>): Partial<AirtableLineItemFields> {
  const fields: Partial<AirtableLineItemFields> = {};

  if (lineItem.service !== undefined) fields['Service'] = lineItem.service;
  if (lineItem.description !== undefined) fields['Description'] = lineItem.description;

  // Use "Price" fields for updates (these seem to be the primary fields)
  if (lineItem.handldRate !== undefined) fields['Handld Price'] = lineItem.handldRate;
  if (lineItem.alaCarteRate !== undefined) fields['A La Carte Price'] = lineItem.alaCarteRate;

  // Convert number frequency back to string for Airtable single-select field
  if (lineItem.chosenFrequency !== undefined) {
    fields['Chosen Frequency'] = lineItem.chosenFrequency ? String(lineItem.chosenFrequency) : undefined;
  }

  if (lineItem.unit !== undefined) fields['Unit'] = lineItem.unit;

  return fields;
}

/**
 * Maps multiple Airtable line item records to our domain models
 */
export function mapAirtableToLineItems(records: AirtableLineItemRecord[]): LineItem[] {
  return records.map(mapAirtableToLineItem);
}

/**
 * Prepares line item updates for Airtable batch update
 */
export function prepareLineItemUpdates(updates: Array<{ id: string; chosenFrequency?: number }>) {
  return updates.map(update => ({
    id: update.id,
    fields: mapLineItemToAirtable({ chosenFrequency: update.chosenFrequency })
  }));
}

/**
 * Airtable module - Public API
 * 
 * This is the main entry point for all Airtable-related functionality.
 * Other parts of the application should import from '@/lib/airtable'
 */

// Export all types
export type {
  // Domain models
  Quote,
  LineItem,
  QuoteTotals,
  QuoteWithLineItems,

  // API types
  QuoteResponse,
  UpdateLineItemsRequest,
  UpdateLineItemsResponse,

  // Component props
  LineItemTableProps,

  // Airtable-specific types (if needed externally)
  AirtableQuoteFields,
  AirtableLineItemFields,
  AirtableQuoteRecord,
  AirtableLineItemRecord
} from './types';

// Export client functions
export {
  getQuoteByToken,
  updateLineItems,
  updateQuote,
  findQuoteByToken
} from './client';

// Export configuration (if needed externally)
export { AIRTABLE_CONFIG } from './config';

// Export mapper functions (if needed externally)
export {
  mapAirtableToQuote,
  mapQuoteToAirtable,
  calculateQuoteTotals,
  mapAirtableToLineItem,
  mapLineItemToAirtable,
  mapAirtableToLineItems,
  prepareLineItemUpdates
} from './mappers';

