    17→
    18→// Validate environment variables
    19→const API_KEY = process.env.AIRTABLE_API_KEY;
    20→const BASE_ID = process.env.AIRTABLE_BASE_ID;
    21→
    22→if (!API_KEY || !BASE_ID) {
    23→  throw new Error('Missing required Airtable credentials: AIRTABLE_API_KEY and AIRTABLE_BASE_ID');
    24→}
    25→
    26→// Configure Airtable
    27→const base = new Airtable({ apiKey: API_KEY }).base(BASE_ID);
    28→
    29→// Optional view configuration
    30→const ALLOWED_VIEW = process.env.AIRTABLE_ALLOWED_VIEW || '';
    31→
    32→/**
    33→ * Fetches a quote by its token, including all associated line items
    34→ */
    35→export async function getQuoteByToken(token: string): Promise<{ 
    36→  quote: Quote; 
    37→  lineItems: LineItem[]; 
    38→  totals: QuoteTotals;
    39→}> {
    40→  try {
    41→    // 1. Find the quote row by Token field
    42→    const quoteRecords = await base(AIRTABLE_CONFIG.QUOTES_TABLE)
    43→      .select({
    44→        filterByFormula: `{${AIRTABLE_CONFIG.TOKEN_FIELD}}='${token}'`,
    45→        maxRecords: 1
    46→      })
    47→      .firstPage();
    48→
    49→    if (!quoteRecords || quoteRecords.length === 0) {
    50→      const error = new Error('Quote not found');
    51→      (error as any).status = 404;
    52→      throw error;
    53→    }
    54→
    55→    const quoteRecord = quoteRecords[0] as unknown as AirtableQuoteRecord;
    56→    const quote = mapAirtableToQuote(quoteRecord);
    57→
    58→    // 2. Fetch line items linked to this quote using Quote ID
    59→    const quoteId = quote.quoteId;
    60→    const lineItemSelectOptions: any = {
    61→      filterByFormula: `{${AIRTABLE_CONFIG.QUOTE_ID_LOOKUP_FIELD}}='${quoteId}'`
    62→    };
    63→    
    64→    if (ALLOWED_VIEW) {
    65→      lineItemSelectOptions.view = ALLOWED_VIEW;
    66→    }
    67→
    68→    const lineItemRecords = await base(AIRTABLE_CONFIG.LINE_ITEMS_TABLE)
    69→      .select(lineItemSelectOptions)
    70→      .all();
    71→    const lineItems = mapAirtableToLineItems(lineItemRecords as unknown as AirtableLineItemRecord[]);
    72→
    73→    // 3. Calculate totals
