import { NextResponse } from 'next/server';
import { AIRTABLE_CONFIG } from '../../../../lib/airtable/config.js';
export const dynamic = 'force-dynamic';

function checkRequired(name, value) {
  return {
    name,
    value: value ? '✓ Set' : '✗ Missing',
    valid: !!value,
    masked: value ? `${value.slice(0, 8)}***` : null
  };
}

function checkOptional(name, value) {
  return {
    name,
    value: value || '(not set)',
    valid: true,
    masked: value ? `${value.slice(0, 8)}***` : null
  };
}

function checkConstant(name, value) {
  return {
    name: `${name} (constant)`,
    value: `✓ ${value}`,
    valid: true,
    masked: null
  };
}

export async function GET() {
  const checks = [
    // Required credentials
    checkRequired('AIRTABLE_API_KEY', process.env.AIRTABLE_API_KEY),
    checkRequired('AIRTABLE_BASE_ID', process.env.AIRTABLE_BASE_ID),

    // Constants (shown for reference)
    checkConstant('QUOTES_TABLE', AIRTABLE_CONFIG.QUOTES_TABLE),
    checkConstant('LINE_ITEMS_TABLE', AIRTABLE_CONFIG.LINE_ITEMS_TABLE),
    checkConstant('TOKEN_FIELD', AIRTABLE_CONFIG.TOKEN_FIELD),
    checkConstant('LINK_FIELD', AIRTABLE_CONFIG.LINK_FIELD),

    // Optional variables
    checkOptional('AIRTABLE_ALLOWED_VIEW', process.env.AIRTABLE_ALLOWED_VIEW),
    checkOptional('NEXT_PUBLIC_API_BASE', process.env.NEXT_PUBLIC_API_BASE),
  ];

  const requiredChecks = ['AIRTABLE_API_KEY', 'AIRTABLE_BASE_ID'];
  const missingRequired = checks.filter(c => 
    requiredChecks.includes(c.name) && !c.valid
  );
  const isReady = missingRequired.length === 0;

  // Test Airtable connection if all required vars are present
  let connectionTest = null;
  if (isReady) {
    try {
      const testUrl = `https://api.airtable.com/v0/${process.env.AIRTABLE_BASE_ID}/${encodeURIComponent(AIRTABLE_CONFIG.QUOTES_TABLE)}?maxRecords=1`;
      const response = await fetch(testUrl, {
        headers: {
          'Authorization': `Bearer ${process.env.AIRTABLE_API_KEY}`,
          'Content-Type': 'application/json'
        }
      });

      connectionTest = {
        success: response.ok,
        status: response.status,
        message: response.ok ? 'Connection successful' : `HTTP ${response.status}: ${await response.text()}`
      };
    } catch (error) {
      connectionTest = {
        success: false,
        status: 'ERROR',
        message: error.message
      };
    }
  }

  return NextResponse.json({
    ready: isReady,
    configuration: checks,
    missingRequired: missingRequired.map(c => c.name),
    connectionTest,
    nextSteps: isReady ? 
      ['✓ Credentials configured', '✓ Airtable connection verified', '✓ Constants loaded', 'Ready to use!'] :
      [
        'Set missing credentials in .env.local',
        'Restart the development server', 
        'Visit this endpoint again to verify'
      ],
    note: 'Table and field names are now constants in lib/airtable/config.ts - no environment variables needed!'
  });
}
